-- CMS seed for the supplied News & Blogs copy. Safe to run more than once.
-- Existing matching slugs are updated; other articles remain untouched.
BEGIN;

ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, "updatedAt"=NOW();

ON CONFLICT (slug) DO UPDATE SET kind=EXCLUDED.kind,title=EXCLUDED.title,summary=EXCLUDED.summary,body=EXCLUDED.body,"coverImage"=EXCLUDED."coverImage","coverImageAlt"=EXCLUDED."coverImageAlt",status=EXCLUDED.status,"publishedAt"=EXCLUDED."publishedAt","updatedAt"=NOW();

COMMIT;
