('news_listing', '{"eyebrow":"Media","heading":"News and updates","intro":"Explore announcements, project updates and market thinking from Kasumigaseki Properties Development."}'::jsonb, NOW())
INSERT INTO articles (id,slug,kind,title,summary,body,"coverImage","coverImageAlt",status,"publishedAt","updatedAt") VALUES
('cms_news_forum','design-underwriting-endurance','NEWS','Design, Underwriting & Endurance Forum','A closed-room discussion on land logic, delivery discipline, design intent, and how long-horizon value is protected before a project reaches market.',$json$["KPD convened a focused forum around the relationship between design, underwriting, and long-term project relevance. The conversation centered on how early feasibility decisions shape every later layer of a development, from frontage and arrival to operations, maintenance, leasing, and resale confidence.","The session treated design as a commercial discipline rather than a decorative layer. Participants discussed why enduring residential value depends on a project being clear about its audience, its service logic, its public edges, and the daily routines it supports.","For KPD, this is where development begins: with the patience to test assumptions, the restraint to avoid unnecessary complexity, and the discipline to make places that remain useful and memorable beyond launch."]$json$::jsonb,'/legacy/assets/images/library/bottom-up-view-of-modern-office-building-in-hong-k-2026-03-26-06-21-57-utc.jpg','Dubai financial district and real estate context','PUBLISHED','2026-06-10T00:00:00Z',NOW()),
('cms_news_sxs','seven-x-seven-project-note','NEWS','seven x seven: Luxury, in balance','A sharper urban mixed-use brief built around positioning, movement, and future delivery logic.',$json$["seven x seven is shaped around an urban reading of density, frontage, and movement. The project is positioned to make its address, arrival sequence, and residential experience feel coherent from the street to the private interior.","Rather than relying on scale alone, the project uses measured facade rhythm, amenity logic, and material restraint to create a residential experience that is composed and commercially legible.","The development reflects KPD's wider approach: every spatial decision should carry operational, experiential, and long-term value."]$json$::jsonb,'/legacy/assets/images/project-media/sxs/facade%20left%202.png','seven x seven facade render','PUBLISHED','2026-06-01T00:00:00Z',NOW()),
('cms_news_villa','emerald-villa-private-preview','NEWS','Villa 174 Private Preview','An invitation-only preview of Villa 174’s planning, amenity story, and garden-led residential experience.',$json$["Villa 174 was presented through a private preview focused on the relationship between arrival, landscape, privacy, and interior calm. The walkthrough introduced the project as a residential environment shaped for family-scaled living and long-horizon ownership.","The preview highlighted the role of garden rooms, shaded outdoor areas, and warm interior materiality in creating a home that feels generous without becoming performative.","KPD's team framed the project as a quieter expression of luxury: one built around clarity, daily use, and a composed sense of permanence."]$json$::jsonb,'/legacy/assets/images/project-media/Emerald%20Villa/12_2.jpg','Villa 174 preview','PUBLISHED','2026-05-22T00:00:00Z',NOW()),
('cms_blog_land','land-logic-before-form','BLOG','Land Logic Before Form','Why site constraints, arrival, frontage, and address behavior shape the earliest development decisions.',$json$["Every durable project begins before architecture. It starts with land logic: what a site allows, what it resists, how it is approached, and how its edges will be read over time.","Frontage, visibility, service access, arrival rhythm, and surrounding movement patterns all influence the kind of product a site can support. Treating those inputs carefully gives a project its first layer of discipline.","When form follows that logic, the architecture has a clearer job. It does not need to compensate for weak positioning; it can refine a proposition that already understands its place."]$json$::jsonb,'/legacy/assets/images/blog/blog-4.jpg','Urban skyline','PUBLISHED','2026-05-10T00:00:00Z',NOW()),
('cms_blog_yield','what-makes-yield-durable','BLOG','What Makes Yield Durable','A note on rental readiness, service-charge discipline, and product features that remain relevant beyond launch.',$json$["Yield durability is rarely created by one headline number. It is built through a sequence of small decisions that make a property easy to understand, easy to operate, and easy to live in.","Rental readiness depends on product clarity, furnishing logic, maintenance discipline, and amenities that support real routines rather than marketing lists. Service-charge control matters because it protects the net experience for owners and tenants alike.","The strongest projects remain legible after launch. They offer a clear reason to be chosen again, not just a reason to be noticed once."]$json$::jsonb,'/legacy/assets/images/blog/blog-5.jpg','Residential landscape','PUBLISHED','2026-04-28T00:00:00Z',NOW()),
('cms_blog_quiet','quiet-architecture','BLOG','Quiet Architecture','How restraint, material clarity, and practical operations can create a stronger residential experience.',$json$["Quiet architecture does not mean passive architecture. It means design that knows when to hold back, when to frame, and when to let daily life take priority.","In residential development, restraint can be a form of confidence. Clear materials, controlled light, practical circulation, and durable details often create a stronger experience than excessive visual noise.","For KPD, the aim is not to make buildings that shout at first glance. It is to make places that continue to feel considered after years of use."]$json$::jsonb,'/legacy/assets/images/blog/blog-6.jpg','Modern facade','PUBLISHED','2026-04-12T00:00:00Z',NOW())
